<?php require '../config/config.php';role('anggota');$q=trim($_GET['q']??'');$rows=[];if($q){$st=$pdo->prepare("SELECT b.code,b.title,b.author,COUNT(c.id) total,COALESCE(SUM(c.status='tersedia'),0) available FROM books b LEFT JOIN copies c ON c.book_id=b.id WHERE b.title LIKE ? OR b.code LIKE ? OR b.author LIKE ? GROUP BY b.id ORDER BY b.title");$x="%$q%";$st->execute([$x,$x,$x]);$rows=$st->fetchAll();}?><!doctype html><html lang=id><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Cari Buku</title><link rel=stylesheet href="../public/style.css"></head><body><?php include 'nav.php'; ?><main style="max-width:1100px;margin:0 auto;padding:24px"><h1>🔎 Cari Buku</h1><form class=search><input name=q value="<?=e($q)?>" placeholder="Judul, kode, atau penulis"><button>Cari</button></form><br><table class=table><tr><th>Kode</th><th>Judul</th><th>Penulis</th><th>Total Eksemplar</th><th>Ketersediaan</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['code'])?></td><td><?=e($r['title'])?></td><td><?=e($r['author']?:'-')?></td><td><?=$r['total']?></td><td><?=$r['available']>0?'🟢 '.$r['available'].' tersedia':'🔴 Tidak tersedia'?></td></tr><?php endforeach?><?php if($q&&!$rows):?><tr><td colspan=5>Buku tidak ditemukan.</td></tr><?php endif?></table></main></body></html>